    use super::structs;

    static mut TEST_KFUNC_NFAILED: c_int = 0;
    static mut REF_CACHE_HTTP_LINE: [c_char; REF_CACHE_BUF_SZ as usize + 1] =
        [0; REF_CACHE_BUF_SZ as usize + 1];

    #[repr(C)]
    struct HFileLayout {
        buffer: *mut c_char,
        begin: *mut c_char,
        end: *mut c_char,
        limit: *mut c_char,
        backend: *const structs::hFILE_backend,
        offset: libc::off_t,
        flags: c_uint,
        has_errno: c_int,
    }

    type BgzfPrivateDataCleanupFunc = unsafe extern "C" fn(*mut c_void);

    #[repr(C)]
    struct BgzfCacheLayout {
        h: *mut c_void,
        last_pos: c_uint,
        private_data: *mut c_void,
        private_data_cleanup: Option<BgzfPrivateDataCleanupFunc>,
    }

