    // original: http_status_errno (htslib/hfile_libcurl.c:130)
    pub unsafe fn hfile_libcurl_c_130_http_status_errno(status: c_int) -> c_int {
        if status >= 500 {
            match status {
                501 => libc::ENOSYS,
                503 => libc::EBUSY,
                504 => libc::ETIMEDOUT,
                _ => libc::EIO,
            }
        } else if status >= 400 {
            match status {
                401 => libc::EPERM,
                403 => libc::EACCES,
                404 => libc::ENOENT,
                405 => libc::EROFS,
                407 => libc::EPERM,
                408 => libc::ETIMEDOUT,
                410 => libc::ENOENT,
                _ => libc::EINVAL,
            }
        } else {
            0
        }
    }

