        let mut pos = len;
        while pos > 0 {
            let c = *name.add(pos);
            if c == b'.' as c_char || c == b'/' as c_char {
                break;
            }
            pos -= 1;
        }

        if pos == 0 || *name.add(pos) != b'.' as c_char {
            return 1;
        }

