    // original: http_status_errno (htslib/hfile_s3.c:1242)
    pub unsafe fn hfile_s3_c_1242_http_status_errno(status: c_int) -> c_int {
        if status >= 500 {
            match status {
                501 => libc::ENOSYS,
                503 => libc::EBUSY,
                504 => libc::ETIMEDOUT,
                _ => libc::EIO,
            }
        } else if status >= 400 {
            match status {
                401 => libc::EPERM,
                403 => libc::EACCES,
                404 => libc::ENOENT,
                405 => libc::EROFS,
                407 => libc::EPERM,
                408 => libc::ETIMEDOUT,
                410 => libc::ENOENT,
                _ => libc::EINVAL,
            }
        } else if status >= 300 {
            libc::EIO
        } else {
            0
        }
    }

