    // original: xstreq (htslib/vcf.c:63)
    pub unsafe fn vcf_c_63_xstreq(mut a: *const c_char, mut b: *const c_char) -> c_int {
        while *a != 0 && *a == *b {
            a = a.add(1);
            b = b.add(1);
        }
        (*a == *b) as c_int
    }

