    // original: is_escaped (htslib/vcf.c:647)
    pub unsafe fn vcf_c_647_is_escaped(min: *const c_char, mut str_: *const c_char) -> c_int {
        let mut n = 0;
        loop {
            str_ = str_.sub(1);
            if str_ < min || *str_ != b'\\' as c_char {
                break;
            }
            n += 1;
        }
        n % 2
    }

