    // original: compare_regions (htslib/hts.c:3361)
    pub unsafe fn hts_c_3361_compare_regions(r1: *const c_void, r2: *const c_void) -> c_int {
        let reg1 = r1.cast::<hts_reglist_t>();
        let reg2 = r2.cast::<hts_reglist_t>();

        if (*reg1).tid < 0 && (*reg2).tid >= 0 {
            1
        } else if (*reg1).tid >= 0 && (*reg2).tid < 0 {
            -1
        } else {
            (*reg1).tid - (*reg2).tid
        }
    }

