    // original: decode_uri (htslib/ref_cache/request_handler.c:56)
    pub unsafe fn ref_cache_request_handler_c_56_decode_uri(
        parser: *mut structs::Http_Parser,
    ) -> *mut c_char {
        let parser_l = parser.cast::<HttpParserLayout>();
        let mut uri = (*parser_l).uri;
        if uri.is_null() {
            return std::ptr::null_mut();
        }

        if libc::strncasecmp(uri, c"http://".as_ptr(), 7) == 0 {
            let localpart = libc::strchr(uri.add(7), b'/' as c_int);
            if localpart.is_null() {
                return std::ptr::null_mut();
            }
            uri = localpart;
        }

        if *uri != b'/' as c_char {
            return std::ptr::null_mut();
        }

        let querypart = libc::strchr(uri, b'?' as c_int);
        if !querypart.is_null() {
            *querypart = 0;
        }

        let mut last: c_char = 0;
        let mut in_ = uri;
        let mut out = uri;
        while *in_ != 0 {
            if *in_ == b'/' as c_char && last == b'/' as c_char {
                in_ = in_.add(1);
                continue;
            }
            if *in_ == b'%' as c_char {
                let d1 = ref_cache_hexval(*in_.add(1));
                let d2 = ref_cache_hexval(*in_.add(2));
                if d1 >= 0 && d2 >= 0 {
                    let v = ((d1 << 4) | d2) as c_char;
                    in_ = in_.add(3);
                    if v == b'/' as c_char && last == b'/' as c_char {
                        continue;
                    }
                    *out = v;
                    last = v;
                    out = out.add(1);
                    continue;
                }
            }
            *out = *in_;
            last = *in_;
            out = out.add(1);
            in_ = in_.add(1);
        }
        *out = 0;
        uri
    }

