    // original: cmp_match_addrs (htslib/ref_cache/main.c:816)
    pub unsafe fn ref_cache_main_c_816_cmp_match_addrs(
        av: *const c_void,
        bv: *const c_void,
    ) -> c_int {
        let a = av.cast::<RefCacheMatchAddrLayout>();
        let b = bv.cast::<RefCacheMatchAddrLayout>();
        let ip_order = if libc::AF_INET < libc::AF_INET6 {
            1
        } else {
            -1
        };

        if (*a).family != (*b).family {
            return ip_order * if (*a).family < (*b).family { -1 } else { 1 };
        }
        libc::memcmp(
            (*a).addr.as_ptr().cast(),
            (*b).addr.as_ptr().cast(),
            (*a).addr.len(),
        )
    }

    // original: sort_match_addrs (htslib/ref_cache/main.c:826)
    pub unsafe fn ref_cache_main_c_826_sort_match_addrs(opts: *mut structs::Options) {
        let opts = opts.cast::<RefCacheOptionsLayout>();
        let mut ip6_seen = false;

        if (*opts).match_addrs.is_null() {
            return;
        }

        let slice = std::slice::from_raw_parts_mut((*opts).match_addrs, (*opts).num_match_addrs);
        slice.sort_by(|a, b| {
            let ip_order = if libc::AF_INET < libc::AF_INET6 {
                1
            } else {
                -1
            };
            let c = if a.family != b.family {
                ip_order * if a.family < b.family { -1 } else { 1 }
            } else {
                unsafe {
                    libc::memcmp(a.addr.as_ptr().cast(), b.addr.as_ptr().cast(), a.addr.len())
                }
            };
            c.cmp(&0)
        });

        let mut i = 0usize;
        let mut j = 0usize;
        while j < (*opts).num_match_addrs {
            if !ip6_seen
                && (*(*opts).match_addrs.add(i)).family == libc::AF_INET6 as libc::sa_family_t
            {
                (*opts).first_ip6 = i;
                ip6_seen = true;
            }
            loop {
                j += 1;
                if !(j < (*opts).num_match_addrs
                    && libc::memcmp(
                        (*opts).match_addrs.add(i).cast(),
                        (*opts).match_addrs.add(j).cast(),
                        std::mem::size_of::<RefCacheMatchAddrLayout>(),
                    ) == 0)
                {
                    break;
                }
            }
            i += 1;
            if j < (*opts).num_match_addrs && i < j {
                std::ptr::copy((*opts).match_addrs.add(j), (*opts).match_addrs.add(i), 1);
            }
        }
        (*opts).num_match_addrs = i;
        if !ip6_seen {
            (*opts).first_ip6 = i;
        }
    }

